DO $guard$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('public.lts_browser_flow_v229(date,date)'::regprocedure) INTO definition; definition:=replace(definition, '(SELECT (a->>''date'')::date FROM jsonb_array_elements(anchors) a WHERE a->>''bank''=x->>''account'')', '(SELECT (anchor_item->>''date'')::date FROM jsonb_array_elements(anchors) anchor_item WHERE anchor_item->>''bank''=x->>''account'')'); EXECUTE definition; END $guard$; NOTIFY pgrst,'reload schema';
